function sanitizePreset(state){if(!state||!state.parameters||!state.camera||!state.animation)return null;const p={...reference};for(const [key,value] of Object.entries(state.parameters)){if(!schema.has(key))continue;const def=schema.get(key),lo=typeof def[2]==='string'?0:def[2],hi=typeof def[2]==='string'?(def[2]==='bool'?1:def[4].length-1):def[3];if(!Number.isFinite(value)||value<lo||value>hi)return null;p[key]=value;}if(p.MinRad>p.MaxRad)return null;const c=state.camera,a=state.animation;if(!['yaw','pitch','distance'].every(k=>Number.isFinite(c[k]))||c.distance<.5||c.distance>500||!Number.isFinite(a.duration)||a.duration<1||a.duration>60||!Number.isFinite(a.progress)||a.progress<0||a.progress>1||typeof a.playing!=='boolean'||![0,1,1.5,2,3].includes(state.quality))return null;return {parameters:p,camera:{yaw:wrapAngle(c.yaw),pitch:wrapAngle(c.pitch),distance:c.distance,roll:Number.isFinite(c.roll)?wrapAngle(c.roll*Math.PI/180)*180/Math.PI:p.CameraRoll},animation:{duration:a.duration,progress:a.progress,playing:a.playing},quality:state.quality};}
